    ]
  },
  {
    "statement": "If two proteins have the same fold (TM-score ≈ 1), then at least one of their native structures corresponds to a global minimum on its free energy landscape.",
    "motivation": "This weakens the original claim to a trivial consequence of O1 applied individually to each protein, removing the unsupported cross-protein implication. It is directly deducible from O1 alone, without needing O4 for the implication.",
    "depends_on": [
      "O1"
    ],
    "factor_sequence": [
      "O1"
    ]
  },
  {
    "statement": "For a single protein, its native structure (global minimum per O1) will have TM-score = 1 when compared to itself.",
    "motivation": "This combines O1 and O4 in a self-referential, checkable way: O1 gives the native structure, and O4's TM-score formula yields 1 for identical structures (d_i = 0). It is a minimal, testable implication.",
    "depends_on": [
