      "O1"
    ]
  },
  {
    "statement": "If two proteins have the same fold (TM-score ≈ 1), then their native structures are both native structures (by definition).",
    "motivation": "This removes the leap by simply applying the definition from O1 separately to each protein, without implying any causal or necessary connection between fold similarity and the global minimum property. It is minimal and directly checkable from O1 and O4.",
    "depends_on": [
      "O1",
      "O4"
    ],
    "factor_sequence": [
      "O4",
      "O1"
    ]
  },
  {
    "statement": "For any protein, its native structure corresponds to the global minimum of its free energy landscape (O1), independent of its similarity to other proteins.",
    "motivation": "This restates O1 explicitly, emphasizing its independence from comparative measures like TM-score. It avoids the unnecessary coupling in H2 and stays strictly within axioms.",
    "depends_on": [
      "O1"
    ],
    "factor_sequence": [
      "O1"
    ]
  },
  {
    "statement": "If two proteins have the same fold (TM-score ≈ 1), then their TM-scores are approximately 1, but this does not alter the applicability of O1 to each individually.",
    "motivation": "This clarifies that fold similarity (O4) and the global minimum property (O1) are orthogonal facts; one does not imply the other beyond their separate truths. It repairs H2 by making the non-interaction explicit.",
    "depends_on": [
      "O1",
      "O4"
    ],
    "factor_sequence": [
      "O4",
      "O1"
    ]
  }
]

